def P(i,t,intro,steps,rules):
  st="".join(f"<li>{s}</li>" for s in steps); ru="".join(f"<li>{r}</li>" for r in rules)
  return (f'<section data-kit="heading" data-id="h-{i}"><h3>{t}</h3></section><section data-kit="prose" data-id="p-{i}"><p>{intro}</p><ol>{st}</ol><p><strong>les règles</strong></p><ul>{ru}</ul></section>')
